This tracks (1) from #144419 (review).
It'll lead to removal of duplicated logic for dictionary object handling below, and make it easier to reason about __dict__ in general.



      pytorch/torch/_dynamo/variables/misc.py


        Lines 1027 to 1074
      in
      d85ae4b







           if ( 




               name in ("__getitem__", "get") 




               and self.name == "__dict__" 




               and not kwargs 




               and args[0].is_python_constant() 




               and isinstance( 




                   self.obj, 




                   ( 




                       variables.UserDefinedObjectVariable, 




                       variables.NNModuleVariable, 




                       variables.UserDefinedClassVariable, 




                   ), 




               ) 




           ): 




               obj = self.obj 




               key = args[0].as_python_constant() 




               if obj.has_key_in_generic_dict(tx, key): 




                   # redirect to var_getattr on the original obj 




                   return obj.var_getattr(tx, key) 









               # Return the default value for get 




               if name == "get": 




                   if len(args) == 2: 




                       return args[1] 




                   else: 




                       return variables.ConstantVariable(None) 









           elif ( 




               name == "__contains__" 




               and self.name == "__dict__" 




               and len(args) == 1 




               and args[0].is_python_constant() 




               and not kwargs 




               and isinstance( 




                   self.obj, 




                   ( 




                       variables.UserDefinedObjectVariable, 




                       variables.NNModuleVariable, 




                       variables.UserDefinedClassVariable, 




                   ), 




               ) 




           ): 




               obj = self.obj 




               key = args[0].as_python_constant() 




               if obj.has_key_in_generic_dict(tx, key): 




                   return variables.ConstantVariable(True) 




               else: 




                   return variables.ConstantVariable(False) 





